function v9Start(scene='commute',tour=false,t='2023-09-08T09:30'){if(!V9.active){V9.saved={mode:V2.mode,at:V2.at,eventId:V2.eventId,origin:V2.origin,destination:V2.destination,vias:[...V2.vias],transport:V2.transport,plans:V2.plans,selected:V2.selected,focus:V2.focus,departure:V2.departure,planned:V2.planned};V9.savedTrip={round:V5.round,stay:V5.stay,returnAt:V5.returnAt,purpose:V5.purpose,weatherPlace:V5.weatherPlace};}V9.active=true;V9.scene=V9SCENES[scene]?scene:'commute';V9.step=tour?0:null;V9.perspective='asof';v9SetTime(t);const c=V9SCENES[V9.scene];Object.assign(V2,{origin:c.origin,destination:c.destination,vias:[...c.vias],page:'dashboard',transport:'公共交通',departure:'immediate',planned:''});Object.assign(V5,{round:c.round,stay:60,purpose:c.purpose,returnAt:'2023-09-08T11:30',weatherPlace:c.destination});save('sy-v3-role',V3.role);save('sy-v9-session',{active:true,scene:V9.scene,step:V9.step,at:V2.at});vRender()}
