function v9Banner(){return `<div class="v9banner"><div><span class="tag orange">历史情景测试 · 独立记录区</span><b>假设现在是 ${esc(dateText(V2.at))}（北京时间）</b><small>只读取此前已公开资料；当前地图底图不重建2023年路网。</small></div><div class="chips"><button data-v9="pick">切换场景</button><button data-v9="tour">开始导览</button><button data-v9="exit">退出测试</button></div></div>`}
const V9STEPS=[{title:'当时公开信息',page:'dashboard',target:'.v8weather',text:'先核对模拟时刻、资料来源和适用范围。09:28公告在09:27不可见；数值缺失不会自动补齐。'},{title:'查询你的行程',page:'dashboard',target:'#v2-journey',text:'地点已预填，可修改。点击查询添加公共交通方案，再切换驾车查询，用比较功能检查两种选择。历史方案只保存地点，不虚构当时路线和时长。'},{title:'核对地点与公告',page:'map',target:'#v6-geographic-map',text:'在地图上点击地点，区分长期隐患、当时公告和未知状态。地图使用当前底图，地点风险不是通行保证。'},{title:'提交新闻测试线索',page:'feedback',target:'#v2-feedback',text:'可以自己填写，也可创建一条基于已公开新闻的测试线索。它不是本人现场观测，更不是当年的真实用户反馈。'},{title:'进入维护端审核',page:'feedback',target:'.maintfilters',text:'点击进入维护端，打开测试反馈，填写核验说明和状态。用户可申请生成上报材料，维护端审批后可以导出；不会发送给官方。'},{title:'体验互助与公益',page:'community',target:'.v7communityhero',text:'可发布任务，也可载入一个私人演示任务体验接单、完成和评价。公益页按资料发布时间展示救援行动，模拟捐赠意向不收款。'},{title:'查看复盘和导出',page:'events',target:'.v9history',text:'切换当时视角与完整复盘，查看专业预测和后来资料。记录会保留当时快照；可以导出报告，也可记录发现的问题。'}];
function v9Tour(){if(V9.step===null)return '';const x=V9STEPS[V9.step];if(!x)return '';return `<aside class="v9tour" aria-label="场景导览"><div class="v9tourcount">${V9.step+1} / ${V9STEPS.length} · ${V9SCENES[V9.scene].title}</div><h3>${x.title}</h3><p>${x.text}</p><div class="chips">${V9.step===3?'<button data-v9="seed-feedback">创建新闻测试线索</button>':''}${V9.step===4?'<button data-v9="maintainer">进入维护端</button><button data-v9="review-workspace">材料审核工作台</button><button data-v9="user">回用户端</button>':''}${V9.step===5?'<button data-v9="seed-task">载入私人演示任务</button>':''}</div><div class="v9tourbuttons"><button data-v9="previous" ${V9.step===0?'disabled':''}>上一步</button><button class="primary" data-v9="next">${V9.step===6?'完成导览':'下一步'}</button><button data-v9="stop-tour">跳过</button></div></aside>`}
