function v9Pick(){vDialog('选择历史情景',`<p>2023年9月深圳暴雨 · 默认模拟09月08日09:30。可以在导览中修改地点，或选择自由探索。</p><div class="v9scenecards">${Object.entries(V9SCENES).map(([id,c])=>`<button data-v9="scene" data-value="${id}"><b>${c.title}</b><span>${c.origin} → ${c.destination}</span><small>${c.description}</small></button>`).join('')}</div><button data-v9="free">自由探索（不启动导览）</button><p class="muted">模拟反馈、任务和捐赠意向存在独立记录区，不修改普通模式中的记录。</p>`)}
const v9TimeBase=vTimeControls;
