const v9WeatherBase=v8Weather;
v8Weather=function(){if(!V9.active)return v9WeatherBase();const facts=v9Published(),warning=facts.find(e=>e.record_id==='SZ-E019'),rain=facts.filter(e=>['SZ-E023','SZ-E025'].includes(e.record_id)),forecast=facts.filter(e=>e.category==='专业预测');return `<section class="v8weather"><div class="row"><div><b>历史天气与预警 · 当时可知资料</b><p class="muted">截至 ${esc(dateText(V2.at))} · 地点 ${esc(V5.weatherPlace)}</p></div><span class="tag ${warning&&V2.at.startsWith('2023-09-08')?'red':'gray'}">${warning&&V2.at.startsWith('2023-09-08')?'09:28公告：红色预警仍生效':'预警状态需核原公告'}</span></div><div class="v9facts">${rain.map(e=>`<div><small>${esc(e.place_text)} · 报道统计</small><b>${e.measurement_value} mm</b><p>${typeof v17ExplainText==='function'?v17ExplainText(e.record_id==='SZ-E023'?'3小时最大滑动雨量':'本轮最大1小时雨量'):(e.record_id==='SZ-E023'?'3小时最大滑动雨量':'本轮最大1小时雨量')}；不是当前时刻${typeof v17ExplainText==='function'?v17ExplainText('雨强'):'雨强'}</p>${v9AsOfLink(e)}</div>`).join('')||'<div><b>精确雨量未取得</b><p>没有当时观测，不能从事后资料提前填入。</p></div>'}<div><small>本站点气温／风速／水深</small><b>未取得</b><p>盐田雨量不能代替罗湖地点观测。</p></div></div><details class="v8weatherdetails" open><summary>当时已发布的专业判断</summary>${forecast.map(e=>`<div class="listitem"><p>${typeof v17ExplainText==='function'?v17ExplainText(e.summary):esc(e.summary)}</p>${v9AsOfLink(e)}</div>`).join('')||'<p>该时刻尚无已收录预测。</p>'}<small>以上是原始定性或范围判断；不拆成逐小时数值，不计算无依据准确率。</small></details><div class="v8weatherfoot"><span>没有当时数值预报，未来24小时曲线暂不生成。</span><button data-v5="report" data-value="历史天气">导出天气报告</button></div></section>`};
const v9FetchBase=vFetchWeather;vFetchWeather=async function(){if(V9.active){toast('历史情景使用已归档资料，不查询今天的天气');return}return v9FetchBase()};
