function v9RainRecap(){return `<details class="card"><summary>事后降雨背景曲线 · ERA5 G03（非站点实测）</summary><p>以下是已收集的事后再分析网格背景，不能作为当时预报输入；不代表极端雨强峰值。</p><svg viewBox="0 0 700 180" role="img" aria-label="事后再分析降水背景"><path d="M30 15V145H685" stroke="#d3dfe4" fill="none"/>${D.weather.map((w,i)=>`<rect x="${34+i*8.8}" y="${145-w.rain/10*120}" width="5" height="${w.rain/10*120}" fill="#71a99a"><title>${w.time} ${w.rain}mm</title></rect>`).join('')}<text x="30" y="169" fill="#7b929a" font-size="11">9月7日00时 → 9月9日23时 · 小时降水mm · 事后资料</text></svg></details>`}
vEventsPage=function(){if(V2.eventId!=='sep2023'&&!V9.active)return v9EventBase();if(V2.eventTab==='now'&&!V9.active)return v9EventBase();if(V2.eventTab==='now'&&V9.active)return v9HistoricalCurrent();const full=V9.perspective==='full',rows=v9TimelineRows(full),chosen=rows.find(e=>e.record_id===V5.timeline);return `<div class="v9history">${vHead('','历史查询与复盘','选时刻看当时，选完整复盘看全程；两种视角共享同一资料库。')}<div class="seg" style="margin-bottom:20px"><button data-v2="event-tab" data-value="past" class="active">过去事件</button><button data-v2="event-tab" data-value="now">正在发生${V9.active?'（模拟）':''}</button></div><section class="card"><div class="row"><div><span class="tag gray">真实事件 · 深圳</span><h2>2023年9月深圳极端强降雨</h2><p>查询范围：9月7日—16日。完整归档27条资料记录；沿线观测与路由仍不完整。</p></div><button class="primary" data-v9="pick">选择情景导览</button></div><div class="v9historycontrols"><div class="field"><label>查看时刻（北京时间）</label><input id="v17-event-clock" type="datetime-local" min="2023-09-07T00:00" max="2023-09-16T23:59" value="${V2.at}"></div><div class="seg"><button data-v9="perspective" data-value="asof" class="${!full?'active':''}">当时视角</button><button data-v9="perspective" data-value="full" class="${full?'active':''}">完整复盘</button></div><button data-v9="apply-history">用此时刻查询出行</button></div><div class="v9facts"><div><small>当前视角已可见</small><b>${rows.length} 条</b></div><div><small>隐患指引</small><b>2023版 · 10街道</b></div><div><small>预测验证</small><b>定性资料</b></div></div><p class="muted">${full?'完整复盘包含后来发布的记录，不能拿来证明当时已知。':'只显示发布不晚于选定时刻的资料；只有日期的来源保守按当日末尾启用。'}</p></section><div class="v9historygrid"><section class="card"><h2>事件时间线</h2><div class="v5timeline">${rows.map(e=>`<button data-v5="timeline" data-value="${e.record_id}" class="${chosen?.record_id===e.record_id?'active':''}"><small>事件 ${esc(e.event_time_text)}<br>发布 ${esc(dateText(e.source_published_at))}</small><b>${esc(e.category)} · ${esc(e.place_text)}</b></button>`).join('')||'<div class="empty">这一时刻尚无已公开记录，仍可查询当年长期隐患指引。</div>'}</div></section><section class="card"><h2>节点详情与依据</h2>${chosen?`<h3>${esc(chosen.place_text)}</h3><p>${typeof v17ExplainText==='function'?v17ExplainText(chosen.summary):esc(chosen.summary)}</p><p class="muted">${typeof v17ExplainText==='function'?v17ExplainText(chosen.caveat):esc(chosen.caveat)}</p>${v9AsOfLink(chosen)}<p><button data-v9="jump-publication" data-value="${chosen.available_at.slice(0,16)}">按公开时刻查询出行 →</button></p>`:'<div class="v8empty"><b>选择左侧时间线节点</b><p>查看原始依据、时间精度，再跳转到出行查询。</p></div>'}${typeof v13EventPanel==='function'&&chosen?v13EventPanel(chosen):''}${v5End('事件节点')}</section></div>${v9ForecastPanel(full)}${full?v9RainRecap():''}${v9Charity(full)}${v5End('历史查询与复盘')}</div>`};
function v9ForecastPanel(full=false){const rows=v9TimelineRows(full).filter(e=>e.category==='专业预测');return `<section class="card" style="margin-top:20px"><h2>专业预测与实际 · 验证范围</h2><div class="tablewrap"><table><tr><th>发布与来源</th><th>预测内容</th><th>后来实际</th><th>可计算误差</th></tr>${rows.map(e=>`<tr><td>${v9AsOfLink(e)}</td><td>${typeof v17ExplainText==='function'?v17ExplainText(e.summary):esc(e.summary)}</td><td>${full?'后续官方资料记录极端降雨及灾害影响；缺少同地点、同统计时段的配对观测。':'后来的观测不提前展示'}</td><td>不计算：范围或时段未完全匹配</td></tr>`).join('')||'<tr><td colspan="4">此时刻尚无已收录专业预测。</td></tr>'}</table></div><div class="notice">AI数值预测模型尚未接入；规则整理不冒充预测。报道提到“列车效应”可解释持续降雨，但不能据此编造某次预测偏差原因。</div></section>`}
function v9HistoricalCurrent(){return vHead('','模拟当时正在发生的事件','历史测试，不代表今天正在发生的灾害。')+`<section class="card"><h2>深圳暴雨 · ${esc(dateText(V2.at))}</h2><p>已公开资料 ${v9Published().length}条；没有新增数据时不推断事件已经恢复。</p>${v9Published().slice(-8).map(e=>`<div class="listitem"><b>${esc(e.category)}</b><p>${typeof v17ExplainText==='function'?v17ExplainText(e.summary):esc(e.summary)}</p>${v9AsOfLink(e)}</div>`).join('')}<button data-v2="event-tab" data-value="past">查看完整历史查询</button></section>`+v9ForecastPanel(false)}
