// Feedback processing uses versioned status snapshots inside the test sandbox.
const V9STATUSFIELDS=['status','conclusion','priority','handling_note','evidence_url','resolution','handled_at','handled_by'];
function v9StateOf(f){return Object.fromEntries(V9STATUSFIELDS.filter(k=>f[k]!==undefined).map(k=>[k,f[k]]))}
function v9Versions(f){if(f._timeline?.length)return f._timeline;const initial={time:f.submitted,state:{status:'待核验'}};return f.handled_at?[initial,{time:f.handled_at,state:v9StateOf(f)}]:[{time:f.submitted,state:v9StateOf(f)}]}
function v9ProjectFeedback(f,at=V2.at){const t=new Date(at+':00+08:00').getTime(),versions=v9Versions(f).filter(v=>new Date(v.time).getTime()<=t).sort((a,b)=>Date.parse(a.time)-Date.parse(b.time));const out={...f,_timeline:v9Versions(f)};V9STATUSFIELDS.forEach(k=>delete out[k]);Object.assign(out,versions.at(-1)?.state||{status:'待核验'});return out}
stored=function(k){const rows=v9StoreBase(v9StorageKey(k));if(!V9.active||!Array.isArray(rows))return rows;const limit=v9Now().getTime();if(k==='sy-v2-feedback')return rows.filter(f=>Date.parse(f.submitted)<=limit).map(f=>v9ProjectFeedback(f));if(k==='sy-v7-reviews'||k==='sy-v3-logs')return rows.filter(x=>Date.parse(x.time)<=limit);if(k==='sy-v9-reports')return rows.filter(x=>Date.parse(x.created)<=limit).map(x=>x.reviewed&&Date.parse(x.reviewed)>limit?{...x,status:'待维护审核',reviewed:null}:x);if(k==='sy-v2-history'||k==='sy-v9-pledges')return rows.filter(x=>Date.parse(x.created)<=limit);if(k==='sy-v7-tasks')return rows.filter(x=>Date.parse(x.created)<=limit).map(x=>{const hs=(x.history||[]).filter(h=>Date.parse(h.time)<=limit).sort((a,b)=>Date.parse(a.time)-Date.parse(b.time)),state=hs.at(-1)?.status||'待接单',out={...x};if(x.history?.length)out.status=state;if(['审核中','待接单'].includes(out.status)){delete out.worker;delete out.workerName;delete out.completion}if(out.status==='已接单')delete out.completion;return out});return rows};
save=function(k,rows){if(!V9.active||!V9KEYS.includes(k)||!Array.isArray(rows))return v9SaveBase(v9StorageKey(k),rows);const old=v9StoreBase(v9StorageKey(k)),limit=v9Now().getTime();if(k==='sy-v2-feedback'){rows=rows.map(f=>{const prior=old.find(x=>x.id===f.id);if(!prior)return {...f,_timeline:[{time:f.submitted,state:v9StateOf(f)}]};const versions=[...v9Versions(prior)],before=v9ProjectFeedback(prior),state=v9StateOf(f);if(JSON.stringify(v9StateOf(before))!==JSON.stringify(state))versions.push({time:v9Now().toISOString(),state});versions.sort((a,b)=>Date.parse(a.time)-Date.parse(b.time));const out={...prior,...f,_timeline:versions};V9STATUSFIELDS.forEach(k=>delete out[k]);Object.assign(out,versions.at(-1).state);return out});const ids=new Set(rows.map(x=>x.id));rows.push(...old.filter(x=>Date.parse(x.submitted)>limit&&!ids.has(x.id)));}else{const ids=new Set(rows.map(x=>x.id));rows.push(...old.filter(x=>Date.parse(x.created||x.time)>limit&&!ids.has(x.id)));}return v9SaveBase(v9StorageKey(k),rows)};
vRender();

